import os, json, csv, numpy as np

N = 26
OUT_DIR = "storage/noesis/nmap/nudged"

REFS = {
    "Noesis_243": {
        "sum_r": 2.6342924,
        "jaccard_file": "pairs_jaccard_{name}_vs_Noesis_243_tol1e8.json"
    },
    "Scientia_259": {
        "sum_r": 2.6358957,
        "jaccard_file": "pairs_jaccard_{name}_vs_Scientia_259_tol1e8.json"
    },
    "Prometheus_298": {
        "sum_r": 2.6359774,
        "jaccard_file": "pairs_jaccard_{name}_vs_Prometheus_298_tol1e8.json"
    }
}

def load_json(p):
    try:
        with open(p, 'r', encoding='utf-8') as f:
            return json.load(f)
    except Exception:
        return None

def save_json(p, obj):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, 'w', encoding='utf-8') as f:
        json.dump(obj, f, indent=2)

def save_csv(p, rows, header):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, 'w', encoding='utf-8', newline='') as f:
        w = csv.writer(f)
        w.writerow(header)
        for r in rows:
            w.writerow(r)

def find_nudged(root="storage/Inquire/nmap/n26"):
    if not os.path.exists(root): return []
    items = []
    for name in sorted(os.listdir(root)):
        p = os.path.join(root, name)
        if os.path.isdir(p) and name.lower().startswith("nudged"):
            items.append((name, p))
    return items

def load_sum_r_from_summary(folder):
    # summary path may be named <name>_summary_tol1e8.json or summary_tol1e8.json
    candidates = [
        os.path.join(folder, "summary_tol1e8.json")
    ]
    # allow prefixed variants
    for fn in os.listdir(folder):
        if fn.endswith("_summary_tol1e8.json"):
            candidates.insert(0, os.path.join(folder, fn))
    for c in candidates:
        obj = load_json(c)
        if obj and "sum_r" in obj:
            try:
                return float(obj["sum_r"])
            except Exception:
                pass
    return None

def load_jaccard(name, ref_key):
    jp = os.path.join(OUT_DIR, name, REFS[ref_key]["jaccard_file"].format(name=name))
    obj = load_json(jp)
    if not obj: return None
    return float(obj.get("jaccard", 0.0))

def construct_packing():
    # Compute delta vs similarity table
    rows = []
    items = find_nudged()
    result = {"tick": None, "items": []}
    for name, path in items:
        sum_r = load_sum_r_from_summary(path)
        entry = {"name": name, "sum_r": sum_r, "refs": {}}
        for ref_key, ref in REFS.items():
            j = load_jaccard(name, ref_key)
            delta = (None if sum_r is None else (ref["sum_r"] - sum_r))
            entry["refs"][ref_key] = {"pairs_jaccard": j, "delta_sum_r": delta}
            rows.append([
                name,
                f"{sum_r:.9f}" if sum_r is not None else "",
                ref_key,
                f"{j:.9f}" if j is not None else "",
                f"{delta:.9f}" if delta is not None else ""
            ])
        result["items"].append(entry)

    save_json(os.path.join(OUT_DIR, "delta_vs_similarity.json"), result)
    save_csv(os.path.join(OUT_DIR, "delta_vs_similarity.csv"),
             rows,
             header=["name","sum_r","ref","pairs_jaccard","delta_sum_r"])

    # Return a trivial valid pack (analysis-only)
    coords = [0.1,0.3,0.5,0.7,0.9]
    centers = [[x,y] for x in coords for y in coords][:25] + [[0.2,0.2]]
    radii = [0.09999]*25 + [0.0414213]
    return np.array(centers, dtype=float), np.array(radii, dtype=float)
